func (circuit *JoltStagesCircuit) Define(api frontend.API) error {
	gcse := circuit.computeGlobalCse(api)
	circuit.verifyConstraint0(api, gcse)
	circuit.verifyConstraint1(api, gcse)
	circuit.verifyConstraint2(api, gcse)
	circuit.verifyConstraint3(api, gcse)
	circuit.verifyConstraint4(api, gcse)
	circuit.verifyConstraint5(api, gcse)
	circuit.verifyConstraint6(api, gcse)
	circuit.verifyConstraint7(api, gcse)
	circuit.verifyConstraint8(api, gcse)
	circuit.verifyConstraint9(api, gcse)
	circuit.verifyConstraint10(api, gcse)
	return nil
}
